export function batchLetter(index){let value=index+1,result='';while(value>0){value--;result=String.fromCharCode(65+value%26)+result;value=Math.floor(value/26);}return result;}
export function ensureBatchNames(state){for(const shift of state.shifts){shift.batchLabels??={};for(const d of state.deliveries.filter(d=>d.shiftId===shift.id&&d.batchId)){if(!shift.batchLabels[d.batchId])shift.batchLabels[d.batchId]='Batch '+batchLetter(Object.keys(shift.batchLabels).length);d.batchLabel=shift.batchLabels[d.batchId];}}}
export function batchName(state,id){return state.shifts.find(s=>s.batchLabels?.[id])?.batchLabels[id]||state.deliveries.find(d=>d.batchId===id)?.batchLabel||'Batch';}
export function scheduledDueSoon(d,at=Date.now()){const when=Date.parse(d.scheduledAt);return Number.isFinite(when)&&when<=Number(at)+10*60000;}
export function scheduledPriority(d,at=Date.now()){return !!d.scheduledAt&&(scheduledDueSoon(d,at)||d.scheduledPriority===true);}
export function priorityBatchOrder(stops,at=Date.now()){return [...stops].sort((a,b)=>{const done=d=>['delivered','canceled'].includes(d.status);if(done(a)!==done(b))return done(a)?-1:1;const rank=d=>done(d)?4:d.recoveryPriority?0:scheduledDueSoon(d,at)?1:scheduledPriority(d,at)?2:3;return rank(a)-rank(b)||(rank(a)>0&&rank(a)<3?Date.parse(a.scheduledAt)-Date.parse(b.scheduledAt):0)||(a.batchPosition??1e6)-(b.batchPosition??1e6);});}
export function applyBatchPriorities(state,at=Date.now()){ensureBatchNames(state);const ids=[...new Set(state.deliveries.filter(d=>d.batchId&&d.status!=='canceled').map(d=>d.batchId))];for(const id of ids){const ordered=priorityBatchOrder(state.deliveries.filter(d=>d.batchId===id&&d.status!=='canceled'),at);ordered.forEach((d,i)=>d.batchPosition=i);for(const r of state.runs.filter(r=>r.batchId===id&&r.status==='active'))r.deliveryIds=[...ordered.filter(d=>r.deliveryIds.includes(d.id)).map(d=>d.id),...r.deliveryIds.filter(key=>!ordered.some(d=>d.id===key))];}}
